function refresh(){document.querySelectorAll('[data-roster]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.roster===profile.settings.costume)));const r=rankFor(profile.rp);$('#class-name').textContent=r.label;const names={morrow:['MORROW','MORROW'],riot:['RIOT','RIOT'],rhea:['RHEA','RHEA'],fighter:['COACH VALE','VALE'],professor:['PROFESSOR SLATE','SLATE'],sergeant:['SERGEANT KNOX','KNOX'],midnight:['UNIT ZERO','ZERO']},name=names[profile.settings.costume]||names.professor;$('.instructor-note h2').textContent=name[0];$('.speaker').textContent=name[1];$('#credit-count').textContent=profile.credits;$('#locker-open').setAttribute('aria-label',`Revenge locker: ${profile.credits} credits`);$('#record-open').setAttribute('aria-label',`Class ${r.label}: ${profile.rp} class points. View progress`);$('#challenge').textContent=`${Math.min(5,profile.week===weekKey()?profile.weekCount:0)} / 5 CLASSES THIS WEEK`;$('#temper-bar').style.width=`${Math.max(4,profile.temper)}%`;$('#temper-text').textContent=profile.temper>30?'Temper: holding a grudge.':profile.temper>0?'Temper: remembers last time.':'Temper: tolerable. For now.';room?.setReduced(reduced());room?.setCostume(profile.settings.costume);room?.setBackground(profile.settings.background);room?.setOutfit(profile.settings.outfit);document.body.classList.toggle('reduced',reduced());$('#sound-toggle').style.opacity=profile.settings.sound?'1':'.55';$('#sound-toggle').setAttribute('aria-label',profile.settings.sound?'Mute sound':'Enable sound');}
function idle(){session=null;persist();stopCamera();releaseWake();room?.setActive(false);room?.setSuspicion(0);suspicion={value:0,stare:0};lastLevel=-1;document.body.classList.remove('live','rage');$('#attention').hidden=true;$('#crack').classList.remove('show');$('#trial-label').hidden=true;$('#tracking-note').textContent='';$('#room-status').textContent='DETENTION HALL';document.title='Detention — Eyes off.';speech(profile.temper?'After last time, I’m keeping an eye on you.':'You. Work. Me. Watching.');$('#dock').innerHTML=`<div class="duration-heading">YOUR NEXT CLASS <span>FOCUS TIME</span></div><div class="durations" aria-label="Session duration">${[25,50,90].map(n=>`<button data-min="${n}" class="${duration===n?'selected':''}">${n} min</button>`).join('')}</div><button class="start-button" id="start">Take your seat <span>↗</span></button><button class="quiet-button" id="demo">Test his patience · 25-second demo</button>`;$$('[data-min]').forEach(b=>b.onclick=()=>{duration=Number(b.dataset.min);$$('[data-min]').forEach(x=>x.classList.toggle('selected',x===b));});$('#start').onclick=setup;$('#demo').onclick=()=>begin({total:25,task:'Test his patience',mode:'demo',demo:true,breakMinutes:0});refresh();}
function setup(){show(`<span class="eyebrow">THE DEAL IS SIMPLE</span><h2>Stay off this device.</h2><p>He works. You work elsewhere. Keep coming back to the screen, and he’ll make it your problem.</p><label for="task">What are you getting done?</label><input id="task" maxlength="100" placeholder="That problem sheet. Finally."><div class="form-row"><div><label for="minutes">Focus minutes</label><input id="minutes" aria-describedby="minutes-error" type="number" min="1" max="180" step="1" value="${duration}"></div><div><label for="break">Break afterwards</label><select id="break"><option value="5">5 minutes</option><option value="10" selected>10 minutes</option><option value="15">15 minutes</option></select></div></div><p id="minutes-error" class="field-error" role="status" hidden></p><label>How does he catch you?</label><label class="choice"><input type="radio" name="mode" value="camera" checked><span><b>Webcam · notice my gaze</b><small>Calibrate first. Your face stays on this device. Works best with your work beside or below the screen.</small></span></label><label class="choice"><input type="radio" name="mode" value="pointer"><span><b>Mouse / touch · notice me interacting</b><small>Move your mouse or touch this page and suspicion grows. Stop interacting and it drops. No camera.</small></span></label><p class="note">Leaving this tab pauses class and loses the perfect bonus. This website cannot block other apps or detect mouse movement outside this page.</p><div class="session-receipt"><span id="setup-summary"></span><small>Finish class: +20 class points · +1 revenge credit</small></div><button class="primary" id="setup-next">Let’s do this</button>`);if(profile.lastSetup){const mode=profile.lastSetup.mode==='pointer'?'pointer':'camera';$(`input[name="mode"][value="${mode}"]`).checked=true;$('#break').value=String([5,10,15].includes(profile.lastSetup.breakMinutes)?profile.lastSetup.breakMinutes:10);}const updateSetup=()=>{const n=Number($('#minutes').value),valid=Number.isInteger(n)&&n>=1&&n<=180,camera=$('input[name="mode"]:checked').value==='camera';$('#minutes').setAttribute('aria-invalid',String(!valid));$('#minutes-error').hidden=valid;$('#minutes-error').textContent=valid?'':'Choose a whole number from 1 to 180 minutes.';$('#setup-next').disabled=!valid;$('#setup-next').textContent=camera?'Set up my camera →':'Start focus session →';$('#setup-summary').textContent=valid?`${n} minutes of focus · ${$('#break').value}-minute break`: 'Set your focus time';};$('#minutes').oninput=updateSetup;$('#break').onchange=updateSetup;$$('input[name="mode"]').forEach(x=>x.onchange=updateSetup);updateSetup();$('#setup-next').onclick=()=>{const n=Number($('#minutes').value);if(!Number.isInteger(n)||n<1||n>180){toast('Choose 1–180 whole minutes.');return;}duration=n;const options={total:n*60,task:$('#task').value.trim()||'Head down. Work done.',mode:$('input[name="mode"]:checked').value,breakMinutes:Number($('#break').value),demo:false};close();options.mode==='camera'?cameraSetup(()=>begin(options)):begin(options);};}
function initAudio(){try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')void audio.resume();}catch{}}
function sound(kind='bell',preview=null){if(!(preview?.enabled??profile.settings.sound))return;const volume=volumeFor(preview?.volume??profile.settings.volume);if(volume===0)return;try{initAudio();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type=kind==='alarm'?'sawtooth':kind==='bang'?'triangle':'sine';const f=kind==='alarm'?440:kind==='bang'?110:kind==='splat'?260:620;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*.35,audio.currentTime+.24);g.gain.setValueAtTime((kind==='alarm'?.045:kind==='bang'?.16:.08)*volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3);o.start();o.stop(audio.currentTime+.31);}catch{}}
