function begin(o){if(!room){toast('Wait for your instructor to finish loading.');return;}if(!o.demo&&o.mode!=='break'){profile.lastSetup={minutes:o.total/60,mode:o.mode,breakMinutes:o.breakMinutes};save();}session={...o,id:crypto.randomUUID(),phase:'focus',remaining:o.total,deadline:Date.now()+o.total*1000,startedAt:Date.now(),graceUntil:Date.now()+3000,paused:false,pauses:0,escapes:0,warnings:0,events:[]};suspicion={value:0,stare:0};lastLevel=-1;latched=false;demoHold=false;demoOverride=null;lastPointer=0;pointerDown=false;document.body.classList.add('live');room?.setActive(true);initAudio();void wake();sessionUI();persist();}
function sessionUI(){if(!session)return;const s=session;$('#trial-label').hidden=!s.demo;$('#room-status').textContent=s.paused?'CLASS PAUSED':s.phase==='break'?'CLASS DISMISSED':'CLASS IN SESSION';$('#dock').innerHTML=`${s.demo?'<button class="demo-control" id="demo-hold">Keep staring · simulated gaze</button>':''}<div class="session-task">${escape(s.task)}</div><div class="session-clock" id="timer">${clock(Math.ceil(remaining()))}</div><div class="session-sub" id="timer-sub">${s.paused?'Paused. He noticed.':s.phase==='break'?'Your break. He can wait.':s.demo?'An automatic demonstration of his breaking point.':'UNTIL YOU GET YOUR REVENGE'}</div><progress class="session-progress" id="session-progress" max="${s.total}" value="${s.total-remaining()}" aria-label="Session elapsed"></progress><div class="session-actions"><button id="pause" class="${s.paused?'resume-button':''}">${s.paused?'Resume':'Pause'}</button><button id="end">${s.demo?'End demo':s.phase==='break'?'Finish break':'End class'}</button></div>`;$('#pause').onclick=()=>session.paused?resume():pause('Take a moment. Class is paused.',true);$('#end').onclick=()=>s.demo||s.phase==='break'?idle():confirmEnd();if(s.demo){const b=$('#demo-hold');b.setAttribute('aria-pressed',String(demoHold));b.onclick=()=>{demoHold=!demoHold;demoOverride=demoHold;b.setAttribute('aria-pressed',String(demoHold));b.textContent=demoHold?'Look away · let him calm down':'Keep staring · simulated gaze';};}$('#tracking-note').textContent=s.mode==='pointer'?'Mouse / touch detection · this page only':s.mode==='camera'?'Camera watchdog · processed on your device':'';}
function pause(reason,count=false){if(!session||session.paused)return;session.remaining=remaining();session.paused=true;if(count&&session.phase==='focus')session.pauses++;releaseWake();if(session.mode==='camera')stopCamera();suspicion={value:0,stare:0};room?.setSuspicion(0);$('#attention').hidden=true;$('#crack').classList.remove('show');document.body.classList.remove('rage');sessionUI();speech(reason);persist();}
