const lines={strict:['Don’t mind me. Mind your work.','…','I saw that.','Don’t make me get up.','GET. OFF. THIS. DEVICE.'],gentle:['One thing at a time.','Quick glance? Fine.','Back to your work.','You know what you came here for.','Eyes away. You’ve got this.'],savage:['Try doing some bloody work.','… You serious?','Your work won’t do itself, genius.','I am THIS close to losing it.','GET OFF THE BLOODY SCREEN.']};
function react(){const v=suspicion.value,l=v===0?0:v<28?1:v<58?2:v<85?3:4;room?.setSuspicion(v);$('#attention').hidden=v<1;$('#meter').value=v;$('#attention-value').textContent=`${Math.round(v)}%`;document.body.classList.toggle('rage',v>85);if(l!==lastLevel){lastLevel=l;speech(lines[profile.settings.tone]?.[l]??lines.strict[l]);}if(v>=99.9&&!latched){latched=true;session.warnings++;session.events.push({minute:Math.floor((session.total-remaining())/60),kind:'rage'});/* Glass appears on physical impact from the character rig. */persist();}if(v<10){latched=false;$('#crack').classList.remove('show');}if(v>=99.9&&Date.now()-lastRageSound>2300){lastRageSound=Date.now();sound('alarm');if(profile.settings.haptics)navigator.vibrate?.([100,80,140]);}}
function tick(){const now=performance.now(),dt=Math.min(.5,(now-previousTick)/1000);previousTick=now;if(!session||session.paused)return;let r=remaining();if(r<=0){session.phase==='break'?idle():finish(true);return;}$('#timer').textContent=clock(Math.ceil(r));$('#session-progress').value=session.total-r;document.title=`${clock(Math.ceil(r))} · Detention`;if(session.phase==='focus'){let signal=false;if(session.demo){const elapsed=session.total-r;signal=demoOverride??((elapsed>=4&&elapsed<12)||(elapsed>=17&&elapsed<23));}else if(session.mode==='pointer'){signal=Date.now()-lastPointer<250||pointerDown;}else{signal=Date.now()-lastSignal<1100?look:null;$('#tracking-note').textContent=tracking==='missing'?'Face out of view · no suspicion added':tracking==='tracking'?'Camera watchdog · estimating screen-facing gaze':'Tracking uncertain · no suspicion added';if(tracking==='stopped'){pause('Camera stopped. Resume to reconnect.');return;}}if(Date.now()<session.graceUntil)signal=false;suspicion=suspicionStep(suspicion,signal,dt,{temper:session.demo?0:profile.temper,gentle:profile.settings.tone==='gentle'});react();if(r<600&&r>598&&!session.taunted){session.taunted=true;speech('Ten minutes until revenge. IF you finish.');}}if(Date.now()-lastSave>2500){lastSave=Date.now();persist();}}
setInterval(tick,100);
function finish(completed){if(!session)return;const s={...session,remaining:remaining()};document.title='Detention — Eyes off.';session=null;stopCamera();releaseWake();persist();room?.setSuspicion(0);document.body.classList.remove('live','rage');$('#attention').hidden=true;$('#crack').classList.remove('show');$('#trial-label').hidden=true;$('#tracking-note').textContent='';if(!s.demo&&!profile.history.some(h=>h.id===s.id)){profile=settle(profile,s,completed);save();}refresh();$('#room-status').textContent=completed?'CLASS DISMISSED':'CLASS ENDED';speech(completed?'Fine. You win this round.':'You can run. You can also come back.');$('#dock').innerHTML=`<button class="start-button" id="result">${completed?'Your turn. Get revenge.':'Try again when you’re ready.'}</button><button class="quiet-button" id="next">${s.demo?'Back to class':completed?`Take a ${s.breakMinutes}-minute break`:'Back to classroom'}</button>`;$('#result').onclick=()=>completed?locker():idle();$('#next').onclick=()=>completed&&!s.demo?startBreak(s.breakMinutes):idle();show(`<span class="eyebrow">${s.demo?'DEMONSTRATION COMPLETE':completed?'CLASS DISMISSED':'NOT YOUR LAST CLASS'}</span><h2>${completed?'Now it’s your turn.':'A setback. Not the end.'}</h2><p>${s.demo?'That was simulated gaze. Choose webcam or mouse mode for a real class. Check the locker for your available revenge credits.':completed?`You finished ${Math.round(s.total/60)} minutes. ${s.warnings} rage warnings. ${s.escapes} departures.<br><b>+${profile.history[0].rp} class points · +1 revenge credit.</b>${profile.history[0].bonus?'<br>Five-class challenge complete: +2 extra credits.':''}`:'−10 class points (minimum zero). No revenge credit. His temper is higher next time; finishing classes brings it back down.'}</p><button class="primary" id="result-close">${completed?'Let me at him':'Back to classroom'}</button>`);$('#result-close').onclick=()=>{close();completed?locker():idle();};sound('bell');}
function startBreak(minutes){begin({total:minutes*60,breakMinutes:0,task:'Break',mode:'break',demo:false});session.phase='break';sessionUI();speech('Take your break. I’ll be here. Unfortunately.');persist();}
function locker(){if(session){toast('Finish class first. Then it’s your turn.');return;}if(rewardBusy)return;const count=profile.week===weekKey()?profile.weekCount:0;show(lockerMarkup(profile.credits,count));let chosen=null;$$('[data-reward]').forEach(button=>button.onclick=()=>{chosen=rewards.find(r=>r.id===button.dataset.reward);$$('[data-reward]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const available=rewardAvailability(chosen.id,profile.credits,count);$('#use-reward').disabled=!available;$('#use-reward').textContent=available?`${chosen.id==='pie'?'Throw the pie':chosen.id==='water'?'Splash him':'Empty the bucket'} · ${chosen.cost} ${chosen.cost===1?'credit':'credits'}`:'Finish a class to earn more';$('#reward-detail').textContent=available?`${chosen.description} You’ll have ${profile.credits-chosen.cost} credits left.`:`You need ${chosen.cost-profile.credits} more ${chosen.cost-profile.credits===1?'credit':'credits'}.`;});$('#use-reward').onclick=()=>{if(chosen)revengeChallenge(chosen.id);};$('#locker-return').onclick=close;}

function revengeChallenge(type){
 if(rewardBusy||session||!room)return;
 if(!['fighter','rhea','morrow','riot'].includes(profile.settings.costume)||reduced()){revenge(type);return;}
 close();rewardBusy=true;room.setSuspicion(0);room.setDodge(true);
 speech('Go on. Try to hit me.');
 $('#dock').innerHTML=`<div class="revenge-game"><div class="revenge-game-heading"><b>SETTLE THE SCORE</b><span id="aim-status" role="status">Wait for the centre</span></div><div class="aim-track" aria-hidden="true"><span class="aim-zone"></span><span id="aim-marker"></span></div><button class="start-button" id="aim-throw">${type==='pie'?'Throw pie':type==='water'?'Splash':'Tip bucket'}</button><button class="quiet-button" id="aim-cancel">Walk away · keep your credits</button><small>Hit the centre zone. Misses are free. A successful throw costs your selected reward’s credits.</small></div>`;
 let stopped=false,frame=0,misses=0,lastAttempt=0;
 const tick=()=>{if(stopped)return;const x=room.getDodge();$('#aim-marker').style.left=`${50+x/0.62*44}%`;$('#aim-throw').classList.toggle('on-target',Math.abs(x)<.23);frame=requestAnimationFrame(tick);};tick();
 const stop=()=>{stopped=true;cancelAnimationFrame(frame);room.setDodge(false);rewardBusy=false;};
 $('#aim-cancel').onclick=()=>{stop();idle();};
 $('#aim-throw').onclick=()=>{const now=performance.now();if(now-lastAttempt<650)return;lastAttempt=now;if(Math.abs(room.getDodge())>=.23&&misses<3){misses++;$('#aim-status').textContent='Dodged. Try again — no credit spent.';speech(['Too slow.','You call that a throw?','All right. One clean shot.'][misses-1]);if(misses===3)room.setDodge(false);return;}stop();revenge(type);};
}
function revenge(type){if(rewardBusy)return;if(!room){toast('Your instructor is still loading. Your credits are safe.');return;}const cost=type==='bucket'?2:1;if(profile.credits<cost||type==='bucket'&&!(profile.week===weekKey()&&profile.weekCount>=5))return;rewardBusy=true;profile.credits-=cost;save();refresh();close();room?.revenge(type);speech(type==='pie'?'… I’m going to remember that.':'THAT IS NOT WHAT I MEANT BY COOLING DOWN.');$('#dock').innerHTML='<div class="session-sub">REVENGE SERVED.</div>';setTimeout(()=>{rewardBusy=false;if(!session){idle();speech('Enjoy your break. Before I change my mind.');}},5000);}
function record(){if(session){toast('The record can wait. Your class is running.');return;}const r=rankFor(profile.rp),h=profile.history,minutes=Math.floor(h.reduce((n,x)=>n+x.seconds,0)/60);show(`<span class="eyebrow">YOUR LOCAL CLASS RECORD</span><h2>Class ${r.label}. Keep climbing.</h2><div class="rank-path">${['0','E','D','C','B','A','Elite'].map(n=>`<span class="${r.label===n?'current':''}">${n}</span>`).join('')}</div><p><b>${profile.rp} class points · ${minutes} minutes · ${h.filter(x=>x.completed).length} completed classes</b></p><p class="note">150 class points per class. Finish: +20. No warnings, pauses or departures: +10 extra. End early: −10. These are local levels, not a global leaderboard.</p>${h.length?h.slice(0,15).map(x=>`<div class="record-row"><div>${escape(x.task)}<small>${new Date(x.date).toLocaleDateString()} · ${Math.round(x.seconds/60)} min · ${x.mode==='camera'?'Webcam':'Mouse / touch'}</small></div><div>${x.completed?x.perfect?'Perfect':'Completed':'Ended early'}<small>${x.rp>0?'+':''}${x.rp} class points</small></div></div>`).join(''):'<p>Your first class goes here. He’s waiting.</p>'}`);}
function settings(){if(session||rewardBusy){toast('Change your instructor between classes.');return;}show(preferencesMarkup(profile.settings));$('#tone').value=profile.settings.tone;for(const k of['sound','haptics','motion'])$('#'+k).checked=profile.settings[k];$('#cracks').checked=profile.settings.crack;let costume=profile.settings.costume;$$('[data-costume]').forEach(b=>b.onclick=()=>{costume=b.dataset.costume;$$('[data-costume]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));room?.setCostume(costume);room?.setOutfit($('#outfit').value);$('#appearance-preview').textContent=`Previewing ${instructors.find(i=>i.id===costume)?.name||'instructor'}. Save to keep this look.`;});for(const key of ['background','outfit'])$$(`[data-${key}]`).forEach(b=>b.onclick=()=>{$('#'+key).value=b.dataset[key];$$(`[data-${key}]`).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));room?.[key==='background'?'setBackground':'setOutfit'](b.dataset[key]);$('#appearance-preview').textContent='Preview updated. Save to keep this look.';});$('#volume').oninput=()=>$('#volume-value').textContent=$('#volume').value+'%';$('#sample-sound').onclick=()=>{if(!$('#sound').checked){toast('Enable sound effects first, then test the volume.');return;}sound('alarm',{enabled:true,volume:Number($('#volume').value)/100});};$('#save-settings').onclick=()=>{profile.settings={...profile.settings,background:$('#background').value,outfit:$('#outfit').value,volume:Number($('#volume').value)/100,tone:$('#tone').value,costume,sound:$('#sound').checked,haptics:$('#haptics').checked,motion:$('#motion').checked,crack:$('#cracks').checked};save();refresh();close();};$('#reset').onclick=()=>{show('<h2>A clean slate?</h2><p>This permanently removes classes, credits and preferences from this browser.</p><button class="primary" id="erase">Erase my local progress</button>');$('#erase').onclick=()=>{profile=fresh();save();close();idle();};};}
function stopCamera(){tracker?.stop();tracker=null;video?.remove();video=null;look=null;tracking='unknown';}
async function cameraSetup(onReady){calibrating=true;const token=++setupToken;show(`<span class="eyebrow">POSITION CHECK</span><h2>Set the device. Then leave it.</h2><p>Phone upright in front or beside you; PC webcam facing you. Put your work away from this screen. Your face needs to be lit and visible.</p><div class="camera-frame" id="camera-frame"><div class="face-oval"></div></div><div class="camera-status" id="camera-status" role="status">Camera off. No frames are recorded or uploaded.</div><button class="primary" id="camera-action">Enable camera</button><p class="note">We compare a screen-facing gaze with your working position. If they look too similar, class will not start. This is an estimate, not medical-grade eye tracking.</p><button class="secondary" id="use-mouse">Use mouse / touch instead</button>`);$('#use-mouse').onclick=()=>{close();if(session){session.mode='pointer';resume();}else{setup();$('input[value="pointer"]').checked=true;}};const error=e=>{if(token!==setupToken)return;$('#camera-status').textContent=e.message;$('#camera-action').disabled=false;};$('#camera-action').onclick=async()=>{const b=$('#camera-action');b.disabled=true;b.textContent='Loading camera check…';try{const{CameraTracker}=await import('./camera.js');if(token!==setupToken)return;const localTracker=new CameraTracker();tracker=localTracker;video=document.createElement('video');video.autoplay=true;video.muted=true;video.playsInline=true;$('#camera-frame').prepend(video);await localTracker.start(video,r=>{look=r.looking;tracking=r.state;lastSignal=Date.now();});if(token!==setupToken){localTracker.stop();return;}b.disabled=false;b.textContent='Capture screen gaze · 3 seconds';$('#camera-status').textContent='Look at the middle of this screen, then press the button.';b.onclick=async()=>{b.disabled=true;$('#camera-status').textContent='Keep looking at this screen. Hold still…';try{await localTracker.capture('screen');if(token!==setupToken)return;b.disabled=false;b.textContent='Capture work gaze · 3 seconds';$('#camera-status').textContent='Press below, then look at your book or work away from this device.';b.onclick=async()=>{b.disabled=true;$('#camera-status').textContent='Look away at your work now…';try{await localTracker.capture('work');if(token!==setupToken)return;localTracker.verify();b.disabled=false;b.textContent='Position checked · start class';$('#camera-status').textContent='Positions are distinguishable. You’ll have 3 seconds to turn back to your work.';b.onclick=()=>{calibrating=false;video.style.cssText='position:fixed;bottom:0;left:0;width:2px;height:2px;opacity:.01;pointer-events:none';document.body.append(video);$('#modal').close();onReady();};}catch(e){error(e);}};}catch(e){error(e);}};}catch(e){if(token!==setupToken)return;stopCamera();b.disabled=false;b.textContent='Retry camera setup';b.onclick=()=>{close();cameraSetup(onReady);};$('#camera-status').textContent=e.name==='NotAllowedError'?'Camera permission declined. Allow access in your browser settings, or choose mouse mode.':e.name==='NotFoundError'?'No camera found. Connect a webcam or choose mouse mode.':e.message?.includes('still pending')?e.message:'Camera setup could not start. Check camera permissions or choose mouse mode.';}};}
document.addEventListener('pointermove',()=>{if(session?.mode==='pointer'&&!session.paused&&!$('#modal').open)lastPointer=Date.now();});document.addEventListener('pointerdown',e=>{if(session?.mode==='pointer'&&!e.target.closest('button,dialog')){pointerDown=true;lastPointer=Date.now();}});document.addEventListener('pointerup',()=>pointerDown=false);document.addEventListener('pointercancel',()=>pointerDown=false);
function departure(){if(!session||session.paused||session.phase==='break')return;session.escapes++;pointerDown=false;demoHold=false;pause('… You left class.');room?.setSuspicion(73);persist();}
document.addEventListener('visibilitychange',()=>{if(document.hidden){departure();persist();}else{tick();if(session&&!session.paused)void wake();}});window.addEventListener('blur',()=>{if(!calibrating)departure();});window.addEventListener('pagehide',()=>{persist();stopCamera();releaseWake();});
$('#sound-toggle').onclick=()=>{profile.settings.sound=!profile.settings.sound;save();initAudio();refresh();sound('bell');};$('#record-open').onclick=record;$('#locker-open').onclick=locker;$('#settings-open').onclick=settings;$('#change-instructor').onclick=settings;$('#home').onclick=()=>rewardBusy?toast('Finish your revenge round or use Walk away.'):session?toast('Your class is running. Use End class to leave.'):idle();$('#about').onclick=()=>show('<span class="eyebrow">ONE RULE</span><h2>Stay off this device.</h2><p>A glance under one second is free. Keep looking and his suspicion rises. Around five seconds: he gets in your face. Look away and he backs down.</p><p>Webcam mode estimates screen-facing gaze. Mouse mode reacts to movement or touch on this page. Both pause your class when you leave. Neither can block other apps.</p><p>Finish a class, earn revenge. Fail and he holds a grudge. Finish more classes to calm him down.</p><p class="note">For iPhone app blocking, the next version needs Apple’s native Screen Time APIs. This is the browser prototype.</p>');
idle();if(!storageOK)toast('Progress cannot be saved in this browser.');
try{const old=savedSession;if(old&&old.phase==='focus'&&Number.isFinite(old.total)&&old.total>0&&old.total<=10800&&Number.isFinite(old.remaining)&&!old.demo&&!profile.history.some(h=>h.id===old.id)){session={...old,remaining:clamp(old.remaining,0,old.total),paused:true,pauses:(old.pauses||0)+1};document.body.classList.add('live');sessionUI();persist();speech('Back again? Your class is saved. Resume when ready.');}}catch{}
try{const{createClassroom}=await import('./scene.js?v=19');room=await createClassroom($('#world'));$('#loading-room')?.remove();room.setSoundHandler((kind,impact)=>{sound(kind);if(kind==='bang'&&session&&!session.paused&&suspicion.value>85&&!reduced()){document.body.classList.remove('impact');void document.body.offsetWidth;document.body.classList.add('impact');if(profile.settings.crack){const crack=$('#crack');if(!crack.classList.contains('show')){const x=impact?.x??.57,y=impact?.y??.4;crack.querySelector('svg').style.transform=`translate(${(x-.57)*100}%, ${(y-.4)*100}%)`;}crack.classList.add('show');}}});refresh();}catch(e){console.error(e);const loading=$('#loading-room');if(loading){loading.classList.add('load-failed');loading.innerHTML='<div><span class="eyebrow">CLASS HAS NOT STARTED</span><h2>Your instructor couldn’t load.</h2><p>Check your connection, then try again. Your saved classes and credits are still here.</p><button class="primary" id="retry-room">Retry loading</button></div>';$('#retry-room').onclick=()=>location.reload();}}
if(document.modelContext?.registerTool){const controller=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'get_focus_status',description:'Read the current focus session and local class progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object.');return{session:session?{mode:session.mode,paused:session.paused,remaining:Math.ceil(remaining())}:null,rank:rankFor(profile.rp).label,credits:profile.credits};}},{signal:controller.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}

for(const button of document.querySelectorAll('[data-roster]'))button.onclick=()=>{if(session||rewardBusy){toast('Choose your company between classes.');return;}profile.settings.costume=button.dataset.roster;save();refresh();document.querySelectorAll('[data-roster]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));speech(button.dataset.roster==='riot'?'Go on. Try me.':button.dataset.roster==='morrow'?'I have all day. You do not.':'Your class. My rules.');};
